-- Conferência (md5 depois):
SELECT empresa_id, md5(instrucoes) AS md5_instrucoes, md5(modulos::text) AS md5_modulos
  FROM public.ia_configuracoes WHERE empresa_id IN ('11111111-1111-1111-1111-111111111111', '99999999-9999-4999-8999-999999999999') ORDER BY 1;

